<?php
$pageTitle = 'Education';
require_once 'includes/header.php';
if ($db && $_SERVER['REQUEST_METHOD'] === 'POST') {
    check_csrf();
    try {
        if (($_POST['form_action'] ?? '') === 'delete') { $stmt = $db->prepare('DELETE FROM education WHERE id = ?'); $stmt->execute([(int) $_POST['id']]); admin_redirect('education.php', 'Education entry deleted.'); }
        if (($_POST['form_action'] ?? '') === 'save') {
            $id = (int) ($_POST['id'] ?? 0); $values = [trim($_POST['institution'] ?? ''), trim($_POST['qualification'] ?? ''), ($_POST['start_year'] ?? '') ?: null, ($_POST['end_year'] ?? '') ?: null, trim($_POST['type'] ?? 'degree'), (int) ($_POST['sort_order'] ?? 0)];
            if ($values[0] === '' || $values[1] === '') { throw new RuntimeException('Institution and qualification are required.'); }
            if ($id) { $values[] = $id; $stmt = $db->prepare('UPDATE education SET institution=?, qualification=?, start_year=?, end_year=?, type=?, sort_order=? WHERE id=?'); } else { $stmt = $db->prepare('INSERT INTO education (institution, qualification, start_year, end_year, type, sort_order) VALUES (?, ?, ?, ?, ?, ?)'); }
            $stmt->execute($values); admin_redirect('education.php', 'Education saved.');
        }
    } catch (Throwable $exception) { $formError = $exception->getMessage(); }
}
$editId = (int) ($_GET['edit'] ?? 0); $edit = null;
if ($editId && $db) { $stmt = $db->prepare('SELECT * FROM education WHERE id=?'); $stmt->execute([$editId]); $edit = $stmt->fetch(); }
$items = $db ? $db->query('SELECT * FROM education ORDER BY sort_order ASC, start_year DESC, id ASC')->fetchAll() : [];
?>
<div class="admin-heading"><div><h1>Education</h1><p>Manage education and certification entries.</p></div><a href="education.php?action=add" class="btn btn-primary"><i data-lucide="plus" aria-hidden="true"></i> Add entry</a></div>
<?php if (!empty($formError)): ?><div class="admin-alert admin-alert--error"><?= admin_escape($formError) ?></div><?php endif; ?>
<?php if ($edit || ($_GET['action'] ?? '') === 'add'): $edit = $edit ?: ['institution'=>'','qualification'=>'','start_year'=>'','end_year'=>'','type'=>'degree','sort_order'=>0]; ?>
<form class="admin-card admin-form" method="post"><?= admin_csrf_field() ?><input type="hidden" name="form_action" value="save"><input type="hidden" name="id" value="<?= (int) ($edit['id'] ?? 0) ?>"><div class="admin-form__grid"><div><label class="form-label" for="institution">Institution</label><input class="form-control" id="institution" name="institution" required value="<?= admin_escape($edit['institution']) ?>"></div><div><label class="form-label" for="qualification">Qualification</label><input class="form-control" id="qualification" name="qualification" required value="<?= admin_escape($edit['qualification']) ?>"></div><div><label class="form-label" for="type">Type</label><select class="form-select" id="type" name="type"><option value="degree" <?= $edit['type'] === 'degree' ? 'selected' : '' ?>>Degree</option><option value="certification" <?= $edit['type'] === 'certification' ? 'selected' : '' ?>>Certification</option><option value="other" <?= $edit['type'] === 'other' ? 'selected' : '' ?>>Other</option></select></div><div><label class="form-label" for="sort_order">Sort order</label><input class="form-control" id="sort_order" name="sort_order" type="number" value="<?= (int) $edit['sort_order'] ?>"></div><div><label class="form-label" for="start_year">Start year</label><input class="form-control" id="start_year" name="start_year" type="number" value="<?= admin_escape($edit['start_year']) ?>"></div><div><label class="form-label" for="end_year">End year</label><input class="form-control" id="end_year" name="end_year" type="number" value="<?= admin_escape($edit['end_year']) ?>"></div></div><div class="admin-form__actions"><a class="btn btn-secondary" href="education.php">Cancel</a><button class="btn btn-primary" type="submit">Save entry</button></div></form>
<?php else: ?><section class="admin-card"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Institution</th><th>Qualification</th><th>Type</th><th>Order</th><th></th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td class="admin-table__title"><?= admin_escape($item['institution']) ?></td><td><?= admin_escape($item['qualification']) ?></td><td><?= admin_escape($item['type']) ?></td><td><?= (int) $item['sort_order'] ?></td><td><div class="admin-row-actions"><a class="admin-icon-button" href="education.php?edit=<?= (int) $item['id'] ?>" aria-label="Edit education"><i data-lucide="pencil" aria-hidden="true"></i></a><form method="post" onsubmit="return confirm('Delete this education entry?');"><?= admin_csrf_field() ?><input type="hidden" name="form_action" value="delete"><input type="hidden" name="id" value="<?= (int) $item['id'] ?>"><button class="admin-icon-button" type="submit" aria-label="Delete education"><i data-lucide="trash-2" aria-hidden="true"></i></button></form></div></td></tr><?php endforeach; ?><?php if (!$items): ?><tr><td colspan="5" class="admin-empty">No education entries yet.</td></tr><?php endif; ?></tbody></table></div></section><?php endif; ?>
<?php require_once 'includes/footer.php';
